from bisect import bisect_left

def calculate_shipping_cost(weight, tier_limits=(5, 10, 20, 50), base_rate=5.00, per_tier_increment=1.00):
    if not isinstance(weight, (int, float)):
        raise TypeError("weight must be a number")
    if weight < 0:
        raise ValueError("weight must be non-negative")
    tier_index = bisect_left(tier_limits, weight)  # counts limits strictly less than weight
    return round(base_rate + per_tier_increment * tier_index, 2)

